export interface ConnectorConfig {
  airtableBaseId: string;
  airtableTableName: string;
  airtableApiKey: string;
  defaultCustomerEmail?: string;
  fetch?: typeof fetch;
}

export interface ShopifyOrderPaidPayload {
  id: string;
  label: string;
  currency: string;
  totals: Array<{
    type: string;
    display_text: string;
    amount: number;
  }>;
  email?: string;
  customer?: {
    email?: string;
  };
  billing_address?: {
    email?: string;
  };
  [key: string]: unknown;
}

export interface HandleResult {
  createdRecordIds: string[];
}

function extractTotalInDollars(totals: ShopifyOrderPaidPayload['totals']): number {
  const totalEntry = totals.find((t) => t.type === 'total');
  if (!totalEntry) {
    throw new Error('No total entry found in totals array');
  }
  return totalEntry.amount / 100;
}

function extractCustomerEmail(
  payload: ShopifyOrderPaidPayload,
  defaultEmail?: string,
): string {
  const email =
    payload.email ??
    payload.customer?.email ??
    payload.billing_address?.email ??
    defaultEmail;
  if (!email) {
    throw new Error(
      'Customer email not found in payload (checked email, customer.email, billing_address.email) and no defaultCustomerEmail provided in config',
    );
  }
  return email;
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  if (!payload.label) {
    throw new Error('Missing required field: label (order number)');
  }
  if (!payload.totals || !Array.isArray(payload.totals) || payload.totals.length === 0) {
    throw new Error('Missing required field: totals array');
  }

  const orderId = payload.label;
  const total = extractTotalInDollars(payload.totals);
  const customerEmail = extractCustomerEmail(payload, config.defaultCustomerEmail);

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableName}`;
  const body = {
    records: [
      {
        fields: {
          'Order ID': orderId,
          'Customer Email': customerEmail,
          Total: total,
        },
      },
    ],
  };

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(
      `Airtable API request failed: ${response.status} ${response.statusText} for POST ${url}`,
    );
  }

  const data = (await response.json()) as {
    records: Array<{ id: string }>;
  };

  const createdRecordIds = data.records.map((r) => r.id);
  return { createdRecordIds };
}

